def word_frequency(text: str) -> dict[str, int]:
    import string
    freq = {}
    if not text:
        return freq
    punct = string.punctuation
    for word in text.split():
        cleaned = word.strip(punct).lower()
        if cleaned:
            freq[cleaned] = freq.get(cleaned, 0) + 1
    return freq
